dispatch(request: Request) -> Elevator:
  bestElevator = null
  bestScore = infinity

  for elevator in elevators:
    if elevator.passengerCount == elevator.capacity:
      continue  // full, skip

    // Score: distance + directional alignment penalty
    distance = abs(elevator.currentFloor - request.sourceFloor)
    penalty = 0

    if elevator.direction != IDLE:
      // If moving up and request is above, no penalty; if below, add penalty
      if elevator.direction == UP and request.sourceFloor < elevator.currentFloor:
        penalty += 5  // opposite direction, higher cost
      elif elevator.direction == DOWN and request.sourceFloor > elevator.currentFloor:
        penalty += 5

    score = distance + penalty

    if score < bestScore:
      bestScore = score
      bestElevator = elevator

  if bestElevator:
    bestElevator.addRequest(request)

  return bestElevator

move():
  if direction == IDLE:
    return  // no pending requests

  if direction == UP:
    currentFloor += 1
  else:
    currentFloor -= 1

  // Check if we've reached a requested floor
  if isAtRequestFloor():
    openDoor()
    // Caller will handle passenger exit/entry

isAtRequestFloor() -> bool:
  for request in requestQueue:
    if request.destinationFloor == currentFloor:
      return true
  return false

openDoor():
  doorState = OPEN
  // In a real system, wait for door to close or timeout
  // For simulation, remove completed requests
  requestQueue.filter(r => r.destinationFloor != currentFloor)

  // Determine next direction
  if requestQueue.isEmpty():
    direction = IDLE
  else:
    // Look at min/max of remaining floors
    minFloor = requestQueue.map(r => r.destinationFloor).min()
    maxFloor = requestQueue.map(r => r.destinationFloor).max()
    if minFloor > currentFloor:
      direction = UP
    else if maxFloor < currentFloor:
      direction = DOWN
    else:
      // Mixed requests, pick one (e.g., UP first)
      direction = UP

  closeDoor()

closeDoor():
  doorState = CLOSED
